### 2. **Sample Code to Compare Excel Files**

Here's a simple example to compare two Excel files and show discrepancies:

```javascript
const fs = require('fs');
const xlsx = require('xlsx');

// Function to read Excel file and return data as array of objects
function readExcelFile(filePath) {
    const workbook = xlsx.readFile(filePath);
    const sheetName = workbook.SheetNames[0]; // Assuming first sheet
    const worksheet = workbook.Sheets[sheetName];
    const data = xlsx.utils.sheet_to_json(worksheet);
    return data;
}

// Function to compare two arrays of objects
function compareData(data1, data2) {
    const discrepancies = [];

    // Check if the number of rows is the same
    if (data1.length !== data2.length) {
        discrepancies.push(`Number of rows differs: ${data1.length} vs ${data2.length}`);
    }

    // Compare each row
    for (let i = 0; i < Math.min(data1.length, data2.length); i++) {
        const row1 = data1[i];
        const row2 = data2[i];

        // Compare each cell in the row
        for (const key in row1) {
            if (row1[key] !== row2[key]) {
                discrepancies.push(`Discrepancy at row ${i + 1}, column "${key}":`);
                discrepancies.push(`  File 1: ${row1[key]}`);
                discrepancies.push(`  File 2: ${row2[key]}`);
            }
        }
    }

    return discrepancies;
}

// Main function
function compareExcelFiles(file1Path, file2Path) {
    const data1 = readExcelFile(file1Path);
    const data2 = readExcelFile(file2Path);

    const discrepancies = compareData(data1, data2);

    if (discrepancies.length === 0) {
        console.log('No discrepancies found.');
    } else {
        console.log('Discrepancies found:');
        discrepancies.forEach(d => console.log(d));
    }
}

